-- M0 target PostgreSQL schema design. Implementation in M1 must translate this
-- to reviewed Drizzle migrations. Do not execute this planning file in production.
-- Better Auth core tables (user, account, session, verification) are generated
-- from its verified PostgreSQL adapter at M1. UUIDs in GLITCH tables refer to
-- the adapter's user primary key after its exact schema is verified.
CREATE TABLE user_role_assignments (user_id uuid NOT NULL, role text NOT NULL CHECK (role IN ('super_admin','content_admin','instructor','student')), granted_by uuid, granted_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role));
CREATE TABLE staff_course_assignments (staff_id uuid NOT NULL, course_id uuid NOT NULL, assigned_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(staff_id,course_id));
CREATE TABLE cohorts (id uuid PRIMARY KEY, course_id uuid NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cohort_memberships (cohort_id uuid NOT NULL REFERENCES cohorts(id), student_id uuid NOT NULL, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(cohort_id,student_id));
CREATE TABLE courses (id uuid PRIMARY KEY, title text NOT NULL, description text NOT NULL DEFAULT '', state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','published','archived')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE staff_student_assignments (staff_id uuid NOT NULL, student_id uuid NOT NULL, course_id uuid NOT NULL REFERENCES courses(id), assigned_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(staff_id,student_id,course_id));
ALTER TABLE cohorts ADD CONSTRAINT cohorts_course_fk FOREIGN KEY(course_id) REFERENCES courses(id);
ALTER TABLE staff_course_assignments ADD CONSTRAINT staff_course_fk FOREIGN KEY(course_id) REFERENCES courses(id);
CREATE TABLE weeks (id uuid PRIMARY KEY, course_id uuid NOT NULL REFERENCES courses(id), position integer NOT NULL, title text NOT NULL, UNIQUE(course_id,position));
CREATE TABLE days (id uuid PRIMARY KEY, week_id uuid NOT NULL REFERENCES weeks(id), position integer NOT NULL, title text NOT NULL, active_minutes integer, UNIQUE(week_id,position));
CREATE TABLE chapters (id uuid PRIMARY KEY, day_id uuid NOT NULL REFERENCES days(id), position integer NOT NULL, title text NOT NULL, UNIQUE(day_id,position));
CREATE TABLE learning_units (id uuid PRIMARY KEY, chapter_id uuid NOT NULL REFERENCES chapters(id), position integer NOT NULL, kind text NOT NULL CHECK(kind IN ('video','exercise','feedback','reflection','handover')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(chapter_id,position));
CREATE TABLE media_assets (id uuid PRIMARY KEY, created_by uuid NOT NULL, title text NOT NULL, state text NOT NULL CHECK(state IN ('uploading','processing','ready','failed','archived')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE media_asset_versions (id uuid PRIMARY KEY, asset_id uuid NOT NULL REFERENCES media_assets(id), version integer NOT NULL, provider_video_id text UNIQUE, duration_seconds numeric(10,3), size_bytes bigint, state text NOT NULL CHECK(state IN ('uploading','processing','ready','failed','archived')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(asset_id,version));
CREATE TABLE media_caption_tracks (id uuid PRIMARY KEY, media_version_id uuid NOT NULL REFERENCES media_asset_versions(id), language_code text NOT NULL, provider_track_id text, transcript text, UNIQUE(media_version_id,language_code));
CREATE TABLE media_processing_events (id uuid PRIMARY KEY, media_version_id uuid NOT NULL REFERENCES media_asset_versions(id), state text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE learning_unit_versions (id uuid PRIMARY KEY, unit_id uuid NOT NULL REFERENCES learning_units(id), version integer NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', learning_objective text NOT NULL DEFAULT '', source_reference text, expected_seconds integer, required boolean NOT NULL DEFAULT true, publication_state text NOT NULL DEFAULT 'draft' CHECK(publication_state IN ('draft','ready_for_review','published','unpublished','archived')), media_version_id uuid REFERENCES media_asset_versions(id), content jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(unit_id,version));
CREATE TABLE exercise_definitions (id uuid PRIMARY KEY, unit_version_id uuid NOT NULL UNIQUE REFERENCES learning_unit_versions(id), template_type text NOT NULL, config jsonb NOT NULL, completion_policy text NOT NULL CHECK(completion_policy IN ('submit_to_complete','feedback_then_continue','instructor_approval','revision_required')));
CREATE TABLE exercise_rubrics (id uuid PRIMARY KEY, definition_id uuid NOT NULL REFERENCES exercise_definitions(id), criterion_key text NOT NULL, description text NOT NULL, weight numeric(6,3), UNIQUE(definition_id,criterion_key));
CREATE TABLE release_conditions (id uuid PRIMARY KEY, dependent_unit_version_id uuid NOT NULL REFERENCES learning_unit_versions(id), prerequisite_unit_id uuid NOT NULL REFERENCES learning_units(id), condition_type text NOT NULL CHECK(condition_type IN ('completed','first_attempt_submitted','review_approved')), UNIQUE(dependent_unit_version_id,prerequisite_unit_id,condition_type));
CREATE TABLE curriculum_releases (id uuid PRIMARY KEY, course_id uuid NOT NULL REFERENCES courses(id), release_number integer NOT NULL, state text NOT NULL CHECK(state IN ('draft','published','retired')), published_by uuid, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(course_id,release_number));
CREATE TABLE curriculum_release_units (id uuid PRIMARY KEY, release_id uuid NOT NULL REFERENCES curriculum_releases(id), unit_id uuid NOT NULL REFERENCES learning_units(id), unit_version_id uuid NOT NULL REFERENCES learning_unit_versions(id), position integer NOT NULL, required boolean NOT NULL, UNIQUE(release_id,position), UNIQUE(release_id,unit_id));
CREATE TABLE curriculum_release_events (id uuid PRIMARY KEY, release_id uuid NOT NULL REFERENCES curriculum_releases(id), actor_id uuid NOT NULL, event text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE enrollments (id uuid PRIMARY KEY, student_id uuid NOT NULL, course_id uuid NOT NULL REFERENCES courses(id), release_id uuid NOT NULL REFERENCES curriculum_releases(id), cohort_id uuid REFERENCES cohorts(id), state text NOT NULL CHECK(state IN ('active','suspended','completed')), last_release_unit_id uuid REFERENCES curriculum_release_units(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(student_id,course_id));
CREATE TABLE enrollment_release_units (enrollment_id uuid NOT NULL REFERENCES enrollments(id), release_unit_id uuid NOT NULL REFERENCES curriculum_release_units(id), assigned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(enrollment_id,release_unit_id));
CREATE TABLE student_unit_progress (enrollment_id uuid NOT NULL, release_unit_id uuid NOT NULL, state text NOT NULL CHECK(state IN ('in_progress','completed')), completed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(enrollment_id,release_unit_id), FOREIGN KEY(enrollment_id,release_unit_id) REFERENCES enrollment_release_units(enrollment_id,release_unit_id));
CREATE TABLE video_watch_sessions (id uuid PRIMARY KEY, enrollment_id uuid NOT NULL, release_unit_id uuid NOT NULL, last_position_seconds numeric(10,3) NOT NULL DEFAULT 0, last_event_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(enrollment_id,release_unit_id) REFERENCES enrollment_release_units(enrollment_id,release_unit_id));
CREATE TABLE video_watch_intervals (id uuid PRIMARY KEY, enrollment_id uuid NOT NULL, release_unit_id uuid NOT NULL, start_seconds numeric(10,3) NOT NULL, end_seconds numeric(10,3) NOT NULL, CHECK(end_seconds>start_seconds), FOREIGN KEY(enrollment_id,release_unit_id) REFERENCES enrollment_release_units(enrollment_id,release_unit_id));
CREATE TABLE student_learning_activity (id uuid PRIMARY KEY, enrollment_id uuid NOT NULL REFERENCES enrollments(id), release_unit_id uuid REFERENCES curriculum_release_units(id), event text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exercise_drafts (enrollment_id uuid NOT NULL, release_unit_id uuid NOT NULL, answer jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(enrollment_id,release_unit_id), FOREIGN KEY(enrollment_id,release_unit_id) REFERENCES enrollment_release_units(enrollment_id,release_unit_id));
CREATE TABLE exercise_attempts (id uuid PRIMARY KEY, enrollment_id uuid NOT NULL, release_unit_id uuid NOT NULL, attempt_number integer NOT NULL, answer jsonb NOT NULL, state text NOT NULL CHECK(state IN ('submitted','awaiting_review','needs_revision','completed')), submitted_at timestamptz NOT NULL DEFAULT now(), UNIQUE(enrollment_id,release_unit_id,attempt_number), FOREIGN KEY(enrollment_id,release_unit_id) REFERENCES enrollment_release_units(enrollment_id,release_unit_id));
CREATE TABLE exercise_feedback (id uuid PRIMARY KEY, attempt_id uuid NOT NULL REFERENCES exercise_attempts(id), reviewer_id uuid NOT NULL, message text NOT NULL, decision text NOT NULL CHECK(decision IN ('needs_revision','completed','formative')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exercise_reviews (id uuid PRIMARY KEY, attempt_id uuid NOT NULL UNIQUE REFERENCES exercise_attempts(id), reviewer_id uuid NOT NULL, rubric_snapshot jsonb NOT NULL, decision text NOT NULL, reviewed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE student_notes (enrollment_id uuid NOT NULL, release_unit_id uuid NOT NULL, body text NOT NULL, revision integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(enrollment_id,release_unit_id), FOREIGN KEY(enrollment_id,release_unit_id) REFERENCES enrollment_release_units(enrollment_id,release_unit_id));
CREATE TABLE private_file_assets (id uuid PRIMARY KEY, enrollment_id uuid NOT NULL REFERENCES enrollments(id), release_unit_id uuid REFERENCES curriculum_release_units(id), provider_key text NOT NULL UNIQUE, name text NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE portfolio_artifacts (id uuid PRIMARY KEY, enrollment_id uuid NOT NULL REFERENCES enrollments(id), release_unit_id uuid REFERENCES curriculum_release_units(id), title text NOT NULL, kind text NOT NULL, current_version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE portfolio_artifact_versions (artifact_id uuid NOT NULL REFERENCES portfolio_artifacts(id), version integer NOT NULL, body text NOT NULL DEFAULT '', file_id uuid REFERENCES private_file_assets(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(artifact_id,version));
CREATE TABLE audit_events (id uuid PRIMARY KEY, actor_id uuid NOT NULL, action text NOT NULL, target_type text NOT NULL, target_id uuid NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_events (id uuid PRIMARY KEY, provider text NOT NULL, provider_event_id text NOT NULL, payload_hash text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, UNIQUE(provider,provider_event_id));
CREATE TABLE content_migration_events (id uuid PRIMARY KEY, enrollment_id uuid NOT NULL REFERENCES enrollments(id), from_release_id uuid NOT NULL REFERENCES curriculum_releases(id), to_release_id uuid NOT NULL REFERENCES curriculum_releases(id), actor_id uuid NOT NULL, mapping jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX enrollment_student_state_idx ON enrollments(student_id,state);
CREATE INDEX release_units_order_idx ON curriculum_release_units(release_id,position);
CREATE INDEX watch_intervals_unit_idx ON video_watch_intervals(enrollment_id,release_unit_id);
CREATE INDEX activity_enrollment_time_idx ON student_learning_activity(enrollment_id,created_at DESC);
CREATE INDEX attempts_queue_idx ON exercise_attempts(state,submitted_at);
CREATE INDEX audit_target_idx ON audit_events(target_type,target_id,created_at DESC);
